  fn handle_mirror_session_disable(&self, sess_hdl: res::SessionHandle_t, direction: DirectionE, dev_tgt: res::DevTargetT, mir_id: MirrorId_t) -> thrift::Result<()>;
  fn handle_mirror_session_enable(&self, sess_hdl: res::SessionHandle_t, direction: DirectionE, dev_tgt: res::DevTargetT, mir_id: MirrorId_t) -> thrift::Result<()>;
  fn handle_mirror_session_pipe_vec_set(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, mir_id: MirrorId_t, pipe_vec: i32) -> thrift::Result<()>;
  fn handle_mirror_session_pipe_vec_get(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, mir_id: MirrorId_t) -> thrift::Result<i32>;
  fn handle_mirror_session_meta_flag_update(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, mir_id: MirrorId_t, flag: MetaFlagE, value: bool) -> thrift::Result<()>;
  fn handle_mirror_session_priority_update(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, mir_id: MirrorId_t, value: bool) -> thrift::Result<()>;
  fn handle_mirror_session_coal_mode_update(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, mir_id: MirrorId_t, value: bool) -> thrift::Result<()>;
  fn handle_mirror_session_get_first(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT) -> thrift::Result<MirrorSessionGetResultT>;
  fn handle_mirror_session_get_next(&self, sess_hdl: res::SessionHandle_t, dev_tgt: res::DevTargetT, id: MirrorId_t, pipe_id: i16) -> thrift::Result<MirrorSessionGetResultT>;
